<?php
/**
 * Content Security Policy violation collector.
 *
 * Browsers POST violation reports here when the CSP is active (report-only or
 * enforcing). The endpoint is deliberately unauthenticated and CSRF-free: the
 * payload is generated by the browser, never by a signed-in user's form.
 *
 * Safety rules applied to untrusted input on this route:
 *  - POST only, small body limit, JSON decoding of a known shape.
 *  - Every value is truncated and control characters are stripped before it is
 *    written to the application log (no newline injection into the log file).
 *  - Nothing from the report is executed, evaluated, echoed back, or used to
 *    build SQL. The response body is always empty.
 *  - Reports are rate limited per client IP with a file-backed counter so the
 *    log cannot be flooded, and the limiter works during a database outage.
 */

declare(strict_types=1);
define('SH_JSON_CONTEXT', true);
require_once dirname(__DIR__) . '/config/config.php';

/** Send an empty response. CSP reporting never needs a body. */
function sh_csp_report_done(int $status): void
{
    if (!headers_sent()) {
        header('Cache-Control: no-store');
        http_response_code($status);
    }
    exit;
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    sh_csp_report_done(405);
}

// Browsers send at most a few KB. Anything larger is not a real report.
$raw = (string)file_get_contents('php://input', false, null, 0, 16384);
if ($raw === '') {
    sh_csp_report_done(204);
}

/**
 * Rate limit for this endpoint, shared with the installer unlock limiter.
 * Returns false when the caller has exceeded $max reports in $window seconds.
 */
function sh_csp_report_allow(string $ip, int $max = 30, int $window = 600): bool
{
    return sh_file_rate_limit('csp', $ip, $max, $window);
}

$ip = function_exists('sh_client_ip') ? sh_client_ip() : (string)($_SERVER['REMOTE_ADDR'] ?? '');
if (!sh_csp_report_allow($ip)) {
    // Silently accept: telling the client it was dropped adds no value and the
    // log must not grow without bound.
    sh_csp_report_done(204);
}

$report = json_decode($raw, true);
$body = null;
if (is_array($report)) {
    $body = $report['csp-report'] ?? $report['body'] ?? null;
}

/** Keep one log field: single line, control characters removed, length capped. */
$clean = static function ($v, int $limit = 200): string {
    if (!is_scalar($v)) { return ''; }
    $s = (string)$v;
    $s = (string)preg_replace('/[\x00-\x1f\x7f]+/', ' ', $s);
    $s = function_exists('sh_scrub_secrets') ? sh_scrub_secrets($s) : $s;
    return trim(mb_substr($s, 0, $limit));
};

if (!is_array($body)) {
    sh_log_line('csp', 'Unparseable violation report received.');
    sh_csp_report_done(204);
}

$directive = $clean($body['effective-directive'] ?? $body['violated-directive'] ?? 'unknown', 80);
$blocked   = $clean($body['blocked-uri'] ?? $body['blockedURL'] ?? '', 200);
$document  = $clean($body['document-uri'] ?? $body['documentURL'] ?? '', 200);
$source    = $clean($body['source-file'] ?? $body['sourceFile'] ?? '', 200);
$line      = $clean($body['line-number'] ?? $body['lineNumber'] ?? '', 12);

sh_log_line('csp', sprintf(
    'CSP violation: directive=%s blocked=%s document=%s source=%s line=%s',
    $directive,
    $blocked !== '' ? $blocked : '-',
    $document !== '' ? $document : '-',
    $source !== '' ? $source : '-',
    $line !== '' ? $line : '-'
));

sh_csp_report_done(204);
